"""Capture Server — dumb receiver for the X capture instrument.

Accepts a single POST /api/capture, validates a recursive node tree (a tweet
together with curated comments, each of which is itself a node with the same
shape), stamps `captured_at` on the root on receipt, and appends one JSON
line to `artefacts.jsonl`. It does nothing else — no enrichment, no dedup, no
analysis.

Fixed defaults:
  - data file: artefacts.jsonl beside this file
  - port: 8765
Each may be overridden by a single env var (CAPTURE_DATA, CAPTURE_PORT).
No config file, no CLI flags.
"""

import json
import os
from datetime import datetime, timezone
from pathlib import Path

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse

DEFAULT_PORT = 8765
DEFAULT_DATA_PATH = Path(__file__).resolve().parent / "artefacts.jsonl"

# tweet_url is the anchor and the only required field on every node; the rest
# (including children) is optional and may be empty.
REQUIRED_FIELDS = ("tweet_url",)

app = FastAPI(title="Capture Server")


def data_path() -> Path:
    return Path(os.environ.get("CAPTURE_DATA", DEFAULT_DATA_PATH))


def append_artefact(artefact: dict, path: Path | None = None) -> None:
    """Append one artefact as a JSON line, write + flush. Returns None."""
    target = path if path is not None else data_path()
    with target.open("a", encoding="utf-8") as f:
        f.write(json.dumps(artefact, ensure_ascii=False) + "\n")
        f.flush()


def validate_node(node, path="root") -> None:
    """Validate a node recursively. Raises ValueError with a descriptive
    message on the first problem found. Every nested child must have a
    tweet_url."""
    if not isinstance(node, dict):
        raise ValueError(f"{path} must be an object")
    if not node.get("tweet_url"):
        raise ValueError(f"{path} is missing required field 'tweet_url'")
    children = node.get("children") or []
    if not isinstance(children, list):
        raise ValueError(f"{path}.children must be a list")
    for i, child in enumerate(children):
        validate_node(child, f"{path}.children[{i}]")


@app.post("/api/capture")
async def capture(request: Request):
    try:
        body = await request.json()
    except Exception:
        return JSONResponse(
            status_code=400, content={"status": "error", "error": "invalid JSON body"}
        )

    if not isinstance(body, dict):
        return JSONResponse(
            status_code=400, content={"status": "error", "error": "payload must be an object"}
        )

    try:
        validate_node(body)
    except ValueError as exc:
        return JSONResponse(
            status_code=400,
            content={"status": "error", "error": str(exc)},
        )

    captured_at = datetime.now(timezone.utc).isoformat()
    artefact = {
        "tweet_url": body["tweet_url"],
        "author": body.get("author", ""),
        "tweet_text": body.get("tweet_text", ""),
        "links": body.get("links", []),
        "parent_url": body.get("parent_url"),
        "notes": body.get("notes", ""),
        "children": body.get("children", []),
        "captured_at": captured_at,
    }

    append_artefact(artefact)
    return {"status": "saved", "captured_at": captured_at}



def main() -> None:
    import uvicorn

    port = int(os.environ.get("CAPTURE_PORT", DEFAULT_PORT))
    uvicorn.run(app, host="127.0.0.1", port=port)


if __name__ == "__main__":
    main()

{
  "manifest_version": 3,
  "name": "Capture",
  "version": "0.1.0",
  "description": "Save X/Twitter posts locally as you browse.",
  "permissions": ["sidePanel", "storage"],
  "host_permissions": [
    "https://x.com/*",
    "https://twitter.com/*",
    "http://127.0.0.1:8765/*"
  ],
  "background": {
    "service_worker": "background.js"
  },
  "content_scripts": [
    {
      "matches": ["https://x.com/*", "https://twitter.com/*"],
      "js": ["content.js"],
      "run_at": "document_idle"
    }
  ],
  "side_panel": {
    "default_path": "sidepanel.html"
  },
  "action": {
    "default_title": "Capture"
  }
}

// Side panel logic for Capture.
// Renders the in-progress capture as a live view: the root tweet plus any
// curated comments nested in an indented tree. Re-renders live when the
// content script adds/removes comments (via background broadcast). On Save it
// POSTs the whole recursive tree to the local server.

(() => {
  "use strict";

  const statusEl = document.getElementById("status");
  const contentEl = document.getElementById("content");
  const authorEl = document.getElementById("author");
  const urlEl = document.getElementById("tweet-url");
  const scrapeWarnEl = document.getElementById("scrape-warning");
  const textEl = document.getElementById("tweet-text");
  const linksEl = document.getElementById("links");
  const notesEl = document.getElementById("notes");
  const contextFieldset = document.getElementById("context-fieldset");
  const contextLegend = document.getElementById("context-legend");
  const contextTree = document.getElementById("context-tree");
  const saveBtn = document.getElementById("save");

  let serverUrl = "http://127.0.0.1:8765/api/capture";
  let current = null; // the root node of the in-progress capture (has children[])

  function setStatus(msg, kind) {
    statusEl.textContent = "";
    statusEl.className = "status " + (kind || "pending");
    statusEl.innerHTML = msg;
  }

  function clearStatus() {
    statusEl.textContent = "";
    statusEl.className = "";
  }

  function renderLinks(list) {
    linksEl.innerHTML = "";
    const arr = Array.isArray(list) ? list : [];
    if (arr.length === 0) {
      const li = document.createElement("li");
      li.className = "empty";
      li.textContent = "No links found.";
      linksEl.appendChild(li);
      return;
    }
    for (const link of arr) {
      const li = document.createElement("li");
      const cb = document.createElement("input");
      cb.type = "checkbox";
      cb.value = link;
      cb.checked = true;
      const label = document.createElement("label");
      label.textContent = link;
      li.appendChild(cb);
      li.appendChild(label);
      linksEl.appendChild(li);
    }
  }

  // Build one comment node row, indented by depth. Comment links are shown
  // plainly (captured automatically; no per-node toggles in v1).
  function nodeEl(node, depth) {
    const div = document.createElement("div");
    div.className = "cnode";
    div.style.paddingLeft = 6 + depth * 16 + "px";

    if (node.author) {
      const a = document.createElement("div");
      a.className = "c-author";
      a.textContent = node.author;
      div.appendChild(a);
    }
    const t = document.createElement("div");
    t.className = "c-text";
    t.textContent = node.tweet_text || "(no text scraped)";
    div.appendChild(t);
    if (node.tweet_url) {
      const u = document.createElement("span");
      u.className = "c-url";
      u.textContent = node.tweet_url;
      div.appendChild(u);
    }
    if (Array.isArray(node.links) && node.links.length) {
      const ul = document.createElement("ul");
      for (const link of node.links) {
        const li = document.createElement("li");
        li.textContent = link;
        ul.appendChild(li);
      }
      div.appendChild(ul);
    }
    return div;
  }

  function renderChildren(parentNode, depth, container) {
    for (const child of parentNode.children || []) {
      container.appendChild(nodeEl(child, depth));
      renderChildren(child, depth + 1, container);
    }
  }

  // Re-render the Context (comments tree) section only — called on live
  // updates so notes/text edits in the panel aren't clobbered.
  function renderContext() {
    const kids = (current && current.children) || [];
    contextFieldset.style.display = kids.length ? "block" : "none";
    contextLegend.textContent = "Context (" + kids.length + ")";
    contextTree.innerHTML = "";
    if (kids.length) renderChildren(current, 1, contextTree);
  }

  function renderRoot() {
    const node = current || {};
    authorEl.textContent = node.author || "Unknown author";
    urlEl.textContent = node.tweet_url || "";
    textEl.value = node.tweet_text || "";
    if (!node.tweet_text && !node.tweet_url) {
      scrapeWarnEl.style.display = "block";
    } else {
      scrapeWarnEl.style.display = "none";
    }
    renderLinks(node.links || []);
  }

  function render(data) {
    current = data || { tweet_url: "", author: "", tweet_text: "", links: [], parent_url: null, notes: "", children: [] };
    renderRoot();
    renderContext();
    notesEl.value = current.notes || "";
    contentEl.style.display = "block";
    clearStatus();
  }

  // Deep-clone current into a tree, apply panel edits (root text, notes,
  // checked root links), and return it for submission.
  function collectArtefact() {
    const tree = JSON.parse(JSON.stringify(current || {}));
    tree.tweet_text = textEl.value.trim();
    tree.notes = notesEl.value.trim();
    const checkedLinks = [];
    for (const li of linksEl.querySelectorAll("li")) {
      const cb = li.querySelector('input[type="checkbox"]');
      if (cb && cb.checked && cb.value) checkedLinks.push(cb.value);
    }
    tree.links = checkedLinks;
    return tree;
  }

  async function submit() {
    if (!(current && current.tweet_url)) {
      setStatus("Nothing to save — no tweet URL.", "error");
      return;
    }
    const artefact = collectArtefact();
    saveBtn.disabled = true;
    setStatus("Saving…", "pending");
    try {
      const resp = await fetch(serverUrl, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(artefact),
      });
      if (!resp.ok) throw new Error("HTTP " + resp.status);
      const body = await resp.json();
      setStatus(
        "Saved ✓ " + (body.captured_at ? "at " + body.captured_at : ""),
        "ok"
      );
      chrome.runtime.sendMessage({ type: "clear-pending-capture" });
      saveBtn.disabled = false;
    } catch (e) {
      setStatus(
        "<strong>Server offline</strong> — restart and try again. Your data is still here.",
        "error"
      );
      saveBtn.disabled = false;
    }
  }

  saveBtn.addEventListener("click", submit);

  // Live updates from the background (content added/removed a comment).
  chrome.runtime.onMessage.addListener((message) => {
    if (!message) return;
    if (message.type === "capture-updated") {
      chrome.runtime.sendMessage({ type: "get-pending-capture" }, (resp) => {
        if (chrome.runtime.lastError || !resp || !resp.data) return;
        current = resp.data;
        renderContext(); // refresh tree only; keep notes/text edits
      });
    } else if (message.type === "capture-cleared") {
      // Capture completed — reset the panel to the empty prompt.
      current = null;
      contentEl.style.display = "none";
      setStatus("Capture complete. Hover a tweet on X and click <strong>Capture</strong> to start again.", "ok");
    }
  });

  // Ask background for the pending capture (survives page navigation).
  chrome.runtime.sendMessage({ type: "get-pending-capture" }, (resp) => {
    if (chrome.runtime.lastError) {
      setStatus("Background unavailable. Reopen the panel.", "error");
      return;
    }
    if (resp && resp.serverUrl) serverUrl = resp.serverUrl;
    if (resp && resp.data) {
      render(resp.data);
    } else {
      contentEl.style.display = "none";
      setStatus("No pending capture. Hover a tweet on X and click <strong>Capture</strong>.", "pending");
    }
  });
})();

===== sdk.md =====
> pi can help you use the SDK. Ask it to build an integration for your use case.

# SDK

The SDK provides programmatic access to pi's agent capabilities. Use it to embed pi in other applications, build custom interfaces, or integrate with automated workflows.

**Example use cases:**
- Build a custom UI (web, desktop, mobile)
- Integrate agent capabilities into existing applications
- Create automated pipelines with agent reasoning
- Build custom tools that spawn sub-agents
- Test agent behavior programmatically

See [examples/sdk/](../examples/sdk/) for working examples from minimal to full control.

## Quick Start

```typescript
import { AuthStorage, createAgentSession, ModelRegistry, SessionManager } from "@earendil-works/pi-coding-agent";

// Set up credential storage and model registry
const authStorage = AuthStorage.create();
const modelRegistry = ModelRegistry.create(authStorage);

const { session } = await createAgentSession({
  sessionManager: SessionManager.inMemory(),
  authStorage,
  modelRegistry,
});

session.subscribe((event) => {
  if (event.type === "message_update" && event.assistantMessageEvent.type === "text_delta") {
    process.stdout.write(event.assistantMessageEvent.delta);
  }
});

await session.prompt("What files are in the current directory?");
```

## Installation

```bash
npm install @earendil-works/pi-coding-agent
```

The SDK is included in the main package. No separate installation needed.

## Core Concepts

### createAgentSession()

The main factory function for a single `AgentSession`.

`createAgentSession()` uses a `ResourceLoader` to supply extensions, skills, prompt templates, themes, and context files. If you do not provide one, it uses `DefaultResourceLoader` with standard discovery.

```typescript
import { createAgentSession, SessionManager } from "@earendil-works/pi-coding-agent";

// Minimal: defaults with DefaultResourceLoader
const { session } = await createAgentSession();

// Custom: override specific options
const { session } = await createAgentSession({
  model: myModel,
  tools: ["read", "bash"],
  sessionManager: SessionManager.inMemory(),
});
```

### AgentSession

The session manages agent lifecycle, message history, model state, compaction, and event streaming.

```typescript
interface AgentSession {
  // Send a prompt and wait for completion
  prompt(text: string, options?: PromptOptions): Promise<void>;

  // Queue messages during streaming
  steer(text: string): Promise<void>;
  followUp(text: string): Promise<void>;

  // Subscribe to events (returns unsubscribe function)
  subscribe(listener: (event: AgentSessionEvent) => void): () => void;

  // Session info
  sessionFile: string | undefined;
  sessionId: string;

  // Model control
  setModel(model: Model): Promise<void>;
  setThinkingLevel(level: ThinkingLevel): void;
  cycleModel(): Promise<ModelCycleResult | undefined>;
  cycleThinkingLevel(): ThinkingLevel | undefined;

  // State access
  agent: Agent;
  model: Model | undefined;
  thinkingLevel: ThinkingLevel;
  messages: AgentMessage[];
  isStreaming: boolean;

  // In-place tree navigation within the current session file
  navigateTree(targetId: string, options?: { summarize?: boolean; customInstructions?: string; replaceInstructions?: boolean; label?: string }): Promise<{ editorText?: string; cancelled: boolean }>;

  // Compaction
  compact(customInstructions?: string): Promise<CompactionResult>;
  abortCompaction(): void;

  // Abort current operation
  abort(): Promise<void>;

  // Cleanup
  dispose(): void;
}
```

Session replacement APIs such as new-session, resume, fork, and import live on `AgentSessionRuntime`, not on `AgentSession`.

### createAgentSessionRuntime() and AgentSessionRuntime

Use the runtime API when you need to replace the active session and rebuild cwd-bound runtime state.
This is the same layer used by the built-in interactive, print, and RPC modes.

`createAgentSessionRuntime()` takes a runtime factory plus the initial cwd/session target. The factory closes over process-global fixed inputs, recreates cwd-bound services for the effective cwd, resolves session options against those services, and returns a full runtime result.

```typescript
import {
  type CreateAgentSessionRuntimeFactory,
  createAgentSessionFromServices,
  createAgentSessionRuntime,
  createAgentSessionServices,
  getAgentDir,
  SessionManager,
} from "@earendil-works/pi-coding-agent";

const createRuntime: CreateAgentSessionRuntimeFactory = async ({ cwd, sessionManager, sessionStartEvent }) => {
  const services = await createAgentSessionServices({ cwd });
  return {
    ...(await createAgentSessionFromServices({
      services,
      sessionManager,
      sessionStartEvent,
    })),
    services,
    diagnostics: services.diagnostics,
  };
};

const runtime = await createAgentSessionRuntime(createRuntime, {
  cwd: process.cwd(),
  agentDir: getAgentDir(),
  sessionManager: SessionManager.create(process.cwd()),
});
```

`AgentSessionRuntime` owns replacement of the active runtime across:

- `newSession()`
- `switchSession()`
- `fork()`
- clone flows via `fork(entryId, { position: "at" })`
- `importFromJsonl()`

Important behavior:

- `runtime.session` changes after those operations
- event subscriptions are attached to a specific `AgentSession`, so re-subscribe after replacement
- if you use extensions, call `runtime.session.bindExtensions(...)` again for the new session
- creation returns diagnostics on `runtime.diagnostics`
- if runtime creation or replacement fails, the method throws and the caller decides how to handle it

```typescript
let session = runtime.session;
let unsubscribe = session.subscribe(() => {});

await runtime.newSession();

unsubscribe();
session = runtime.session;
unsubscribe = session.subscribe(() => {});
```

### Prompting and Message Queueing

`PromptOptions` controls prompt expansion, queueing behavior while streaming, and prompt preflight notifications:

```typescript
interface PromptOptions {
  expandPromptTemplates?: boolean;
  images?: ImageContent[];
  streamingBehavior?: "steer" | "followUp";
  source?: InputSource;
  preflightResult?: (success: boolean) => void;
}
```

`preflightResult` is called once per `prompt()` invocation:

- `true` when the prompt was accepted, queued, or handled immediately
- `false` when prompt preflight rejected before acceptance

It fires before `prompt()` resolves. `prompt()` still resolves only after the full accepted run finishes, including retries. Failures after acceptance are reported through the normal event and message stream, not through `preflightResult(false)`.

The `prompt()` method handles prompt templates, extension commands, and message sending:

```typescript
// Basic prompt (when not streaming)
await session.prompt("What files are here?");

// With images
await session.prompt("What's in this image?", {
  images: [{ type: "image", source: { type: "base64", mediaType: "image/png", data: "..." } }]
});

// During streaming: must specify how to queue the message
await session.prompt("Stop and do this instead", { streamingBehavior: "steer" });
await session.prompt("After you're done, also check X", { streamingBehavior: "followUp" });
```

**Behavior:**
- **Extension commands** (e.g., `/mycommand`): Execute immediately, even during streaming. They manage their own LLM interaction via `pi.sendMessage()`.
- **File-based prompt templates** (from `.md` files): Expanded to their content before sending or queueing.
- **During streaming without `streamingBehavior`**: Throws an error. Use `steer()` or `followUp()` directly, or specify the option.
- **`preflightResult(true)`**: Means the prompt was accepted, queued, or handled immediately.
- **`preflightResult(false)`**: Means preflight rejected before acceptance.

For explicit queueing during streaming:

```typescript
// Queue a steering message for delivery after the current assistant turn finishes its tool calls
await session.steer("New instruction");

// Wait for agent to finish (delivered only when agent stops)
await session.followUp("After you're done, also do this");
```

Both `steer()` and `followUp()` expand file-based prompt templates but error on extension commands (extension commands cannot be queued).

### Agent and AgentState

The `Agent` class (from `@earendil-works/pi-agent-core`) handles the core LLM interaction. Access it via `session.agent`.

```typescript
// Access current state
const state = session.agent.state;

// state.messages: AgentMessage[] - conversation history
// state.model: Model - current model
// state.thinkingLevel: ThinkingLevel - current thinking level
// state.systemPrompt: string - system prompt
// state.tools: AgentTool[] - available tools
// state.streamingMessage?: AgentMessage - current partial assistant message
// state.errorMessage?: string - latest assistant error

// Replace messages (useful for branching or restoration)
session.agent.state.messages = messages; // copies the top-level array

// Replace tools
session.agent.state.tools = tools; // copies the top-level array

// Wait for agent to finish processing
await session.agent.waitForIdle();
```

### Events

Subscribe to events to receive streaming output and lifecycle notifications.

```typescript
session.subscribe((event) => {
  switch (event.type) {
    // Streaming text from assistant
    case "message_update":
      if (event.assistantMessageEvent.type === "text_delta") {
        process.stdout.write(event.assistantMessageEvent.delta);
      }
      if (event.assistantMessageEvent.type === "thinking_delta") {
        // Thinking output (if thinking enabled)
      }
      break;

    // Tool execution
    case "tool_execution_start":
      console.log(`Tool: ${event.toolName}`);
      break;
    case "tool_execution_update":
      // Streaming tool output
      break;
    case "tool_execution_end":
      console.log(`Result: ${event.isError ? "error" : "success"}`);
      break;

    // Message lifecycle
    case "message_start":
      // New message starting
      break;
    case "message_end":
      // Message complete
      break;

    // Agent lifecycle
    case "agent_start":
      // Agent started processing prompt
      break;
    case "agent_end":
      // Agent finished (event.messages contains new messages)
      break;

    // Turn lifecycle (one LLM response + tool calls)
    case "turn_start":
      break;
    case "turn_end":
      // event.message: assistant response
      // event.toolResults: tool results from this turn
      break;

    // Session events (queue, compaction, retry)
    case "queue_update":
      console.log(event.steering, event.followUp);
      break;
    case "compaction_start":
    case "compaction_end":
    case "auto_retry_start":
    case "auto_retry_end":
      break;
  }
});
```

## Options Reference

### Directories

```typescript
const { session } = await createAgentSession({
  // Working directory for DefaultResourceLoader discovery
  cwd: process.cwd(), // default

  // Global config directory
  agentDir: "~/.pi/agent", // default (expands ~)
});
```

`cwd` is used by `DefaultResourceLoader` for:
- Project extensions (`.pi/extensions/`)
- Project skills:
  - `.pi/skills/`
  - `.agents/skills/` in `cwd` and ancestor directories (up to git repo root, or filesystem root when not in a repo)
- Project prompts (`.pi/prompts/`)
- Context files (`AGENTS.md` walking up from cwd)
- Session directory naming

`agentDir` is used by `DefaultResourceLoader` for:
- Global extensions (`extensions/`)
- Global skills:
  - `skills/` under `agentDir` (for example `~/.pi/agent/skills/`)
  - `~/.agents/skills/`
- Global prompts (`prompts/`)
- Global context file (`AGENTS.md`)
- Settings (`settings.json`)
- Custom models (`models.json`)
- Credentials (`auth.json`)
- Sessions (`sessions/`)

When you pass a custom `ResourceLoader`, `cwd` and `agentDir` no longer control resource discovery. They still influence session naming and tool path resolution.

### Model

```typescript
import { getModel } from "@earendil-works/pi-ai";
import { AuthStorage, ModelRegistry } from "@earendil-works/pi-coding-agent";

const authStorage = AuthStorage.create();
const modelRegistry = ModelRegistry.create(authStorage);

// Find specific built-in model (doesn't check if API key exists)
const opus = getModel("anthropic", "claude-opus-4-5");
if (!opus) throw new Error("Model not found");

// Find any model by provider/id, including custom models from models.json
// (doesn't check if API key exists)
const customModel = modelRegistry.find("my-provider", "my-model");

// Get only models that have valid API keys configured
const available = await modelRegistry.getAvailable();

const { session } = await createAgentSession({
  model: opus,
  thinkingLevel: "medium", // off, minimal, low, medium, high, xhigh

  // Models for cycling (Ctrl+P in interactive mode)
  scopedModels: [
    { model: opus, thinkingLevel: "high" },
    { model: haiku, thinkingLevel: "off" },
  ],

  authStorage,
  modelRegistry,
});
```

If no model is provided:
1. Tries to restore from session (if continuing)
2. Uses default from settings
3. Falls back to first available model

> See [examples/sdk/02-custom-model.ts](../examples/sdk/02-custom-model.ts)

### API Keys and OAuth

API key resolution priority (handled by AuthStorage):
1. Runtime overrides (via `setRuntimeApiKey`, not persisted)
2. Stored credentials in `auth.json` (API keys or OAuth tokens)
3. Environment variables (`ANTHROPIC_API_KEY`, `OPENAI_API_KEY`, etc.)
4. Fallback resolver (for custom provider keys from `models.json`)

```typescript
import { AuthStorage, ModelRegistry } from "@earendil-works/pi-coding-agent";

// Default: uses ~/.pi/agent/auth.json and ~/.pi/agent/models.json
const authStorage = AuthStorage.create();
const modelRegistry = ModelRegistry.create(authStorage);

const { session } = await createAgentSession({
  sessionManager: SessionManager.inMemory(),
  authStorage,
  modelRegistry,
});

// Runtime API key override (not persisted to disk)
authStorage.setRuntimeApiKey("anthropic", "sk-my-temp-key");

// Custom auth storage location
const customAuth = AuthStorage.create("/my/app/auth.json");
const customRegistry = ModelRegistry.create(customAuth, "/my/app/models.json");

const { session } = await createAgentSession({
  sessionManager: SessionManager.inMemory(),
  authStorage: customAuth,
  modelRegistry: customRegistry,
});

// No custom models.json (built-in models only)
const simpleRegistry = ModelRegistry.inMemory(authStorage);
```

> See [examples/sdk/09-api-keys-and-oauth.ts](../examples/sdk/09-api-keys-and-oauth.ts)

### System Prompt

Use a `ResourceLoader` to override the system prompt:

```typescript
import { createAgentSession, DefaultResourceLoader } from "@earendil-works/pi-coding-agent";

const loader = new DefaultResourceLoader({
  systemPromptOverride: () => "You are a helpful assistant.",
});
await loader.reload();

const { session } = await createAgentSession({ resourceLoader: loader });
```

> See [examples/sdk/03-custom-prompt.ts](../examples/sdk/03-custom-prompt.ts)

### Tools

Specify which built-in tools to enable:

- Built-in tool names: `read`, `bash`, `edit`, `write`, `grep`, `find`, `ls`
- Default built-ins: `read`, `bash`, `edit`, `write`
- `noTools: "all"` disables all tools
- `noTools: "builtin"` disables default built-ins while keeping extension and custom tools enabled

```typescript
import { createAgentSession } from "@earendil-works/pi-coding-agent";

// Read-only mode
const { session } = await createAgentSession({
  tools: ["read", "grep", "find", "ls"],
});

// Pick specific tools
const { session } = await createAgentSession({
  tools: ["read", "bash", "grep"],
});
```

#### Tools with Custom cwd

When you pass a custom `cwd`, `createAgentSession()` builds selected built-in tools for that cwd.

```typescript
import { createAgentSession, SessionManager } from "@earendil-works/pi-coding-agent";

const cwd = "/path/to/project";

// Use default tools for custom cwd
const { session } = await createAgentSession({
  cwd,
  sessionManager: SessionManager.inMemory(cwd),
});

// Or pick specific tools for custom cwd
const { session } = await createAgentSession({
  cwd,
  tools: ["read", "bash", "grep"],
  sessionManager: SessionManager.inMemory(cwd),
});
```

> See [examples/sdk/05-tools.ts](../examples/sdk/05-tools.ts)

### Custom Tools

```typescript
import { Type } from "typebox";
import { createAgentSession, defineTool } from "@earendil-works/pi-coding-agent";

// Inline custom tool
const myTool = defineTool({
  name: "my_tool",
  label: "My Tool",
  description: "Does something useful",
  parameters: Type.Object({
    input: Type.String({ description: "Input value" }),
  }),
  execute: async (_toolCallId, params) => ({
    content: [{ type: "text", text: `Result: ${params.input}` }],
    details: {},
  }),
});

// Pass custom tools directly
const { session } = await createAgentSession({
  customTools: [myTool],
});
```

Use `defineTool()` for standalone definitions and arrays like `customTools: [myTool]`. Inline `pi.registerTool({ ... })` already infers parameter types correctly.

Custom tools passed via `customTools` are combined with extension-registered tools. Extensions loaded by the ResourceLoader can also register tools via `pi.registerTool()`.

If you pass `tools`, include each custom or extension tool name you want enabled, for example `tools: ["read", "bash", "my_tool"]`.

> See [examples/sdk/05-tools.ts](../examples/sdk/05-tools.ts)

### Extensions

Extensions are loaded by the `ResourceLoader`. `DefaultResourceLoader` discovers extensions from `~/.pi/agent/extensions/`, `.pi/extensions/`, and settings.json extension sources.

```typescript
import { createAgentSession, DefaultResourceLoader } from "@earendil-works/pi-coding-agent";

const loader = new DefaultResourceLoader({
  additionalExtensionPaths: ["/path/to/my-extension.ts"],
  extensionFactories: [
    (pi) => {
      pi.on("agent_start", () => {
        console.log("[Inline Extension] Agent starting");
      });
    },
  ],
});
await loader.reload();

const { session } = await createAgentSession({ resourceLoader: loader });
```

Extensions can register tools, subscribe to events, add commands, and more. See [extensions.md](extensions.md) for the full API.

**Event Bus:** Extensions can communicate via `pi.events`. Pass a shared `eventBus` to `DefaultResourceLoader` if you need to emit or listen from outside:

```typescript
import { createEventBus, DefaultResourceLoader } from "@earendil-works/pi-coding-agent";

const eventBus = createEventBus();
const loader = new DefaultResourceLoader({
  eventBus,
});
await loader.reload();

eventBus.on("my-extension:status", (data) => console.log(data));
```

> See [examples/sdk/06-extensions.ts](../examples/sdk/06-extensions.ts) and [docs/extensions.md](extensions.md)

