const MAX_BYTES = 1024 * 1024; // ~1 MB
const TIMEOUT_MS = 30000;

async function fetchWithCaps(url) {
  // validate http(s)
  let parsed;
  try { parsed = new URL(url); } catch { return { ok:false, text:`Invalid URL: ${url}` }; }
  if (!/^https?:$/.test(parsed.protocol)) return { ok:false, text:`Unsupported protocol: ${parsed.protocol}` };
