// fetch_url custom tool for the capture agent.
//
// The ONLY tool the agent gets in v1 (Decision 03): fetch-and-read a url,
// server-side so there is no browser CORS. Bounded with hard caps (body size,
// timeout) so one huge page cannot stall a session. The agent decides which of
// the capture's urls to fetch.

import { defineTool } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";
import { request } from "undici";

export const MAX_BODY_BYTES = 1024 * 1024; // ~1 MB response body cap
export const TIMEOUT_MS = 30_000; // 30 s overall cap
export const MAX_REDIRECTIONS = 5;

// Strip markup so the model reads prose, not HTML soup. Kept deliberately
// lightweight — not a full HTML parser.
function htmlToText(html) {
  return html
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/\s+/g, " ")
    .trim();
}

// Fetch a url with caps. Returns { ok, text } — text is always a string the
// model can read (content on success, an error message on failure).
export async function fetchWithCaps(url) {
  let parsed;
  try {
    parsed = new URL(url);
  } catch {
    return { ok: false, text: `fetch_url: invalid URL: ${url}` };
  }
  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    return { ok: false, text: `fetch_url: unsupported protocol "${parsed.protocol}" (only http/https)` };
  }

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);

  let res;
  try {
    res = await request(parsed.href, {
      signal: controller.signal,
      maxRedirections: MAX_REDIRECTIONS,
      headersTimeout: TIMEOUT_MS,
      bodyTimeout: TIMEOUT_MS,
      headers: {
        "user-agent": "capture-agent-service/0.1 (local reasoning agent)",
        accept: "text/html,text/plain;q=0.9,*/*;q=0.8",
      },
    });
  } catch (e) {
    clearTimeout(timer);
    const reason = e && e.name === "AbortError" ? `timed out after ${TIMEOUT_MS / 1000}s` : e && e.message ? e.message : "unknown fetch error";
    return { ok: false, text: `fetch_url: ${reason}` };
  }
  clearTimeout(timer);

  const status = res.statusCode || 0;
  const contentType = String(res.headers && (res.headers["content-type"] || "")).toLowerCase();

  if (status < 200 || status >= 300) {
    await res.body.dump?.().catch(() => {});
    return { ok: false, text: `fetch_url: HTTP ${status} for ${url}` };
  }

  const declaredLength = parseInt(String(res.headers && res.headers["content-length"] || "0"), 10);
  if (declaredLength > MAX_BODY_BYTES) {
    await res.body.dump?.().catch(() => {});
    return { ok: false, text: `fetch_url: response too large (${declaredLength} bytes > 1 MB cap)` };
  }

  const chunks = [];
  let total = 0;
  let tooLarge = false;
  for await (const chunk of res.body) {
    total += chunk.length;
    if (total > MAX_BODY_BYTES) {
      tooLarge = true;
      break;
    }
    chunks.push(chunk);
  }
  if (tooLarge) {
    return { ok: false, text: "fetch_url: response body exceeded 1 MB cap, content truncated" };
  }

  let bodyText;
  try {
    bodyText = Buffer.concat(chunks).toString("utf8");
  } catch {
    bodyText = "";
  }

  const isHtml = contentType.includes("html");
  const text = (isHtml ? htmlToText(bodyText) : bodyText).slice(0, MAX_BODY_BYTES * 2);
  if (!text.trim()) {
    return { ok: false, text: `fetch_url: no readable text content at ${url}` };
  }
  return { ok: true, text };
}

export const fetchUrlTool = defineTool({
  name: "fetch_url",
  label: "Fetch URL",
  description:
    "Fetch and read the text content of a URL (HTML or plain text). Runs server-side, body capped at ~1 MB and 30s timeout. Use only for urls present in the capture being analyzed.",
  parameters: Type.Object({
    url: Type.String({ description: "The http(s) URL to fetch and read." }),
  }),
  execute: async (_toolCallId, params) => {
    const { ok, text } = await fetchWithCaps(params.url);
    return {
      content: [{ type: "text", text }],
      details: { ok, url: params.url },
    };
  },
});

// Serialize a capture tree into a compact text block that is injected inline
// into the agent's first prompt. This is the "context injection" seam: the
// root tweet plus curated comment nodes (text + urls) become the raw material
// the agent reasons over.

function nodeToText(node, depth, lines) {
  const pad = "  ".repeat(depth);
  const author = node.author ? `${node.author}` : "unknown author";
  const text = node.tweet_text && node.tweet_text.trim() ? node.tweet_text.trim() : "(no text)";
  lines.push(`${pad}- ${author}: ${text}`);
  if (Array.isArray(node.links) && node.links.length) {
    for (const link of node.links) {
      lines.push(`${pad}  url: ${link}`);
    }
  }
  if (node.tweet_url) {
    lines.push(`${pad}  source: ${node.tweet_url}`);
  }
  if (node.notes && node.notes.trim()) {
    lines.push(`${pad}  notes: ${node.notes.trim()}`);
  }
  for (const child of node.children || []) {
    nodeToText(child, depth + 1, lines);
  }
}

export function serializeTree(tree) {
  const lines = [];
  lines.push("Here is the pending capture you are being asked about:");
  nodeToText(tree || {}, 0, lines);
  return lines.join("\n");
}

// Serialize a capture tree into a compact text block that is injected inline
// into the agent's first prompt. This is the "context injection" seam: the
// root tweet plus curated comment nodes (text + urls) become the raw material
// the agent reasons over.

function nodeToText(node, depth, lines) {
  const pad = "  ".repeat(depth);
  const author = node.author ? `${node.author}` : "unknown author";
  const text = node.tweet_text && node.tweet_text.trim() ? node.tweet_text.trim() : "(no text)";
  lines.push(`${pad}- ${author}: ${text}`);
  if (Array.isArray(node.links) && node.links.length) {
    for (const link of node.links) {
      lines.push(`${pad}  url: ${link}`);
    }
  }
  if (node.tweet_url) {
    lines.push(`${pad}  source: ${node.tweet_url}`);
  }
  if (node.notes && node.notes.trim()) {
    lines.push(`${pad}  notes: ${node.notes.trim()}`);
  }
  for (const child of node.children || []) {
    nodeToText(child, depth + 1, lines);
  }
}

export function serializeTree(tree) {
  const lines = [];
  lines.push("Here is the pending capture you are being asked about:");
  nodeToText(tree || {}, 0, lines);
  return lines.join("\n");
}

