@app.get("/search")
async def search(q: str = "", author: str | None = None, since: str | None = None, limit: int = 50):
    """Read API over the derived FTS5 index (BM25 relevance-ranked).

    GET /search?q=arxiv&author=@user&since=2026-08-01T00:00:00+00:00&limit=50

    The index is derived from artefacts.jsonl; if it does not exist yet it is
    rebuilt on the fly so a fresh checkout still answers.
    """
    idx = _index()
    if not idx.exists():
        # derived + rebuildable: safest to build on first read so /search works
        # right after a fresh start without a manual rebuild step.
        try:
            idx.rebuild(data_path())
        except Exception:
            return JSONResponse(status_code=500, content={"status": "error", "error": "could not build index"})

    try:
        items, total = idx.search(q=q or None, author=author or None, since=since or None, limit=limit)
    except ValueError as exc:
        return JSONResponse(status_code=400, content={"status": "error", "error": str(exc)})
    except Exception as exc:  # pragma: no cover - defensive
        return JSONResponse(status_code=500, content={"status": "error", "error": str(exc)})
    return {"items": items, "total": total, "rank": True}

