saveBtn.addEventListener("click", submit);

// ------------------------------------------------------------------------
// Agent (Ask) — stories 1-5
// ------------------------------------------------------------------------

function setAgentStatus(msg, kind) {
  if (!msg) {
    agentStatus.style.display = "none";
    agentStatus.className = "status";
    agentStatus.textContent = "";
    return;
  }
  agentStatus.style.display = "block";
  agentStatus.className = "status " + (kind || "pending");
  agentStatus.textContent = msg;
}

function showAgentUnavailable() {
  agentUnavailable.style.display = "block";
  agentFieldset.style.opacity = "0.75";
}

function hideAgentUnavailable() {
  agentUnavailable.style.display = "none";
  agentFieldset.style.opacity = "";
}

function addAgentBubble(cls, text) {
  const div = document.createElement("div");
  div.className = "agent-msg " + cls;
  div.textContent = text || "";
  agentThread.appendChild(div);
  return div;
}

function updateAgentControls() {
  agentAskBtn.disabled = agentBusy || !!(current && current.tweet_url) === false;
  agentAbortBtn.style.display = agentBusy ? "inline-block" : "none";
  agentAskBtn.style.display = agentBusy ? "none" : "inline-block";
}

function captureId() {
  return current && current.tweet_url ? "capture:" + current.tweet_url : "capture:active";
}

function appendDeliveredText(bubble, text) {
  bubble.textContent += text;
  agentThread.scrollTop = agentThread.scrollHeight;
}

function flushPendingIfConnected() {
  if (agentPending && agentClient && agentClientWasOpen()) {
    agentClient.ask(agentPending.captureId, agentPending.tree, agentPending.prompt, agentPending.messages);
    agentPending = null;
  }
}

function agentClientWasOpen() {
  return agentClient && agentClient.ws && agentClient.ws.readyState === WebSocket.OPEN;
}

function initAgentClient() {
  if (agentClient) return;
  agentClient = new AgentClient({
    url: agentUrl,
    handlers: {
      onReady: () => {
        agentEverAvail = true;
        hideAgentUnavailable();
        setAgentStatus("Connected.", "ok");
        setTimeout(() => setAgentStatus(null), 1200);
        flushPendingIfConnected();
      },
      onDelta: (msg) => {
        if (msg.captureId !== captureId()) return;
        if (!currentAssistantBubble) currentAssistantBubble = addAgentBubble("assistant", "");
        appendDeliveredText(currentAssistantBubble, msg.text);
      },
      onTool: (msg) => {
        if (msg.captureId !== captureId()) return;
        addAgentBubble("tool", "⚙ fetched " + (msg.arg || msg.tool));
      },
      onSettled: (msg) => {
        if (msg.captureId !== captureId()) return;
        // finalize assistant bubble, stash the envelope for Save
        if (!currentAssistantBubble) currentAssistantBubble = addAgentBubble("assistant", "");
        if (msg.model) {
          const meta = document.createElement("div");
          meta.className = "muted";
          meta.style.cssText = "margin-top:4px;font-size:11px;";
          meta.textContent = "model " + msg.model + (typeof msg.cost === "number" ? " · $" + msg.cost.toFixed(5) : "");
          currentAssistantBubble.appendChild(meta);
        }
        currentAssistantBubble = null;
        agentEnvelope = {
          sessionId: msg.sessionId,
          sessionFile: msg.sessionFile,
          prompt: lastAgentPrompt || "",
          model: msg.model || "",
          capturedAt: new Date().toISOString(),
          cost: typeof msg.cost === "number" ? msg.cost : undefined,
        };
        agentMessages.push({ role: "assistant", content: lastAssistantText() });
        agentBusy = false;
        updateAgentControls();
        setAgentStatus("Answer saved with this capture.", "ok");
        setTimeout(() => setAgentStatus(null), 1500);
      },
      onError: (msg) => {
        agentBusy = false;
        updateAgentControls();
        if (msg && /unreachable|unavailable/i.test(msg.message || "")) {
          showAgentUnavailable();
          setAgentStatus("Agent unavailable. You can still save.", "error");
        } else {
          setAgentStatus("Agent error: " + ((msg && msg.message) || "unknown"), "error");
        }
      },
      onDown: (msg) => {
        // service is not up yet — show the unavailable state, keep retrying
        showAgentUnavailable();
        setAgentStatus("Agent unavailable. You can still save.", "error");
      },
    },
  });
  agentClient.connect();
}

let currentAssistantBubble = null;
let lastAgentPrompt = "";
function lastAssistantText() {
  // walking the DOM is fragile; we track the final bubble text via a ref.
  return agentClient ? (agentClient._lastAssistantText || "") : "";
}

function askAgent() {
  if (!(current && current.tweet_url)) {
    setStatus("Nothing to ask about — no tweet URL.", "error");
    return;
  }
  const prompt = agentInput.value.trim();
  if (!prompt) return;
  if (agentBusy) return;

  const tree = collectArtefact();
  lastAgentPrompt = prompt;
  addAgentBubble("user", prompt);
  agentMessages.push({ role: "user", content: prompt });
  agentInput.value = "";
  currentAssistantBubble = null;
  agentBusy = true;
  updateAgentControls();
  hideAgentUnavailable();

  if (agentClientWasOpen()) {
    agentClient.ask(captureId(), tree, prompt, []);
  } else {
    agentPending = { captureId: captureId(), tree, prompt, messages: agentMessages.slice() };
    setAgentStatus("Connecting to agent service…", "pending");
    initAgentClient();
  }
}

function followUpAgent() {
  if (agentBusy) return;
  const prompt = agentInput.value.trim();
  if (!prompt) return;
  if (!agentEverAvail) {
    askAgent();
    return;
  }
  lastAgentPrompt = prompt;
  addAgentBubble("user", prompt);
  agentMessages.push({ role: "user", content: prompt });
  agentInput.value = "";
  currentAssistantBubble = null;
  agentBusy = true;
  updateAgentControls();
  if (agentClientWasOpen()) {
    agentClient.followUp(captureId(), prompt);
  } else {
    agentPending = { captureId: captureId(), tree: collectArtefact(), prompt, messages: agentMessages.slice() };
    setAgentStatus("Reconnecting to agent service…", "pending");
    initAgentClient();
  }
}

agentInput.addEventListener("keydown", (e) => {
  if (e.key === "Enter") {
    e.preventDefault();
    if (agentEverAvail) followUpAgent();
    else askAgent();
  }
});
agentAskBtn.addEventListener("click", askAgent);
agentAbortBtn.addEventListener("click", () => {
  if (agentClient) agentClient.abort(captureId());
  agentBusy = false;
  currentAssistantBubble = null;
  updateAgentControls();
  setAgentStatus("Stopped.", "pending");
});

function resetAgentForNewCapture() {
  agentEnvelope = null;
  agentMessages = [];
  lastAgentPrompt = "";
  currentAssistantBubble = null;
