    agentFieldset.style.opacity = "0.75";
  }

  function hideAgentUnavailable() {
    agentUnavailable.style.display = "none";
    agentFieldset.style.opacity = "";
  }

  function addAgentBubble(cls, text) {
    const div = document.createElement("div");
    div.className = "agent-msg " + cls;
    div.textContent = text || "";
    agentThread.appendChild(div);
    return div;
  }

  function updateAgentControls() {
    agentAskBtn.disabled = agentBusy || !!(current && current.tweet_url) === false;
    agentAbortBtn.style.display = agentBusy ? "inline-block" : "none";
    agentAskBtn.style.display = agentBusy ? "none" : "inline-block";
  }

  function captureId() {
    return current && current.tweet_url ? "capture:" + current.tweet_url : "capture:active";
  }

  function appendDeliveredText(text) {
    if (!currentAssistantBubble) currentAssistantBubble = addAgentBubble("assistant", "");
    currentAssistantBubble.textContent += text;
    currentAssistantText += text;
    agentThread.scrollTop = agentThread.scrollHeight;
  }

  function flushPendingIfConnected() {
    if (agentPending && agentClient && agentClientWasOpen()) {
      agentClient.ask(agentPending.captureId, agentPending.tree, agentPending.prompt, agentPending.messages);
      agentPending = null;
    }
  }

  function agentClientWasOpen() {
    return agentClient && agentClient.ws && agentClient.ws.readyState === WebSocket.OPEN;
  }

  function initAgentClient() {
    if (agentClient) return;
    agentClient = new AgentClient({
      url: agentUrl,
      handlers: {
        onReady: () => {
          agentEverAvail = true;
          hideAgentUnavailable();
          setAgentStatus("Connected.", "ok");
          setTimeout(() => setAgentStatus(null), 1200);
          flushPendingIfConnected();
        },
        onDelta: (msg) => {
          if (msg.captureId !== captureId()) return;
          appendDeliveredText(msg.text);
        },
        onTool: (msg) => {
          if (msg.captureId !== captureId()) return;
          addAgentBubble("tool", "⚙ fetched " + (msg.arg || msg.tool));
        },
        onSettled: (msg) => {
          if (msg.captureId !== captureId()) return;
          // finalize assistant bubble, stash the envelope for Save
          if (!currentAssistantBubble) currentAssistantBubble = addAgentBubble("assistant", "");
          if (msg.model) {
            const meta = document.createElement("div");
            meta.className = "muted";
            meta.style.cssText = "margin-top:4px;font-size:11px;";
            meta.textContent = "model " + msg.model + (typeof msg.cost === "number" ? " · $" + msg.cost.toFixed(5) : "");
            currentAssistantBubble.appendChild(meta);
          }
          currentAssistantBubble = null;
          agentEnvelope = {
            sessionId: msg.sessionId,
            sessionFile: msg.sessionFile,
            prompt: lastAgentPrompt || "",
            model: msg.model || "",
            capturedAt: new Date().toISOString(),
            cost: typeof msg.cost === "number" ? msg.cost : undefined,
          };
          agentMessages.push({ role: "assistant", content: currentAssistantText });
          currentAssistantText = "";
          agentBusy = false;
          updateAgentControls();
          setAgentStatus("Answer saved with this capture.", "ok");
          setTimeout(() => setAgentStatus(null), 1500);
        },
        onError: (msg) => {
          agentBusy = false;
          updateAgentControls();
          if (msg && /unreachable|unavailable/i.test(msg.message || "")) {
            showAgentUnavailable();
            setAgentStatus("Agent unavailable. You can still save.", "error");
          } else {
            setAgentStatus("Agent error: " + ((msg && msg.message) || "unknown"), "error");
          }
        },
        onDown: (msg) => {
          // service is not up yet — show the unavailable state, keep retrying
          showAgentUnavailable();
          setAgentStatus("Agent unavailable. You can still save.", "error");
        },
      },
    });
    agentClient.connect();
  }

  let currentAssistantBubble = null;
  let currentAssistantText = "";
  let lastAgentPrompt = "";

  function askAgent() {
    if (!(current && current.tweet_url)) {
      setStatus("Nothing to ask about — no tweet URL.", "error");
