// fetch_url custom tool for the capture agent.
//
// The ONLY tool the agent gets in v1 (Decision 03): fetch-and-read a url,
// server-side so there is no browser CORS. Bounded with hard caps (body size,
// timeout) so one huge page cannot stall a session. The agent decides which of
// the capture's urls to fetch.

import { defineTool } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";

export const MAX_BODY_BYTES = 1024 * 1024; // ~1 MB response body cap
export const TIMEOUT_MS = 30_000; // 30 s overall cap

// Strip markup so the model reads prose, not HTML soup. Kept deliberately
// lightweight — not a full HTML parser.
function htmlToText(html) {
  return html
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/\s+/g, " ")
    .trim();
}

// Fetch a url with caps using the runtime's global fetch (handles redirects).
// Returns { ok, text } — text is always a string the model can read.
export async function fetchWithCaps(url) {
  let parsed;
  try {
    parsed = new URL(url);
  } catch {
    return { ok: false, text: `fetch_url: invalid URL: ${url}` };
  }
  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    return { ok: false, text: `fetch_url: unsupported protocol "${parsed.protocol}" (only http/https)` };
  }

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);

  let res;
  try {
    res = await fetch(parsed.href, {
      signal: controller.signal,
      redirect: "follow",
      headers: {
        "user-agent": "capture-agent-service/0.1 (local reasoning agent)",
        accept: "text/html,text/plain;q=0.9,*/*;q=0.8",
      },
    });
  } catch (e) {
    clearTimeout(timer);
    const reason = e && e.name === "AbortError" ? `timed out after ${TIMEOUT_MS / 1000}s` : e && e.message ? e.message : "unknown fetch error";
    return { ok: false, text: `fetch_url: ${reason}` };
  }

  if (!res.ok) {
    clearTimeout(timer);
    if (res.body && res.body.cancel) await res.body.cancel().catch(() => {});
    return { ok: false, text: `fetch_url: HTTP ${res.status} for ${url}` };
  }

  const contentType = String(res.headers.get("content-type") || "").toLowerCase();
  const declaredLength = parseInt(String(res.headers.get("content-length") || "0"), 10);
  if (declaredLength > MAX_BODY_BYTES) {
    clearTimeout(timer);
    if (res.body && res.body.cancel) await res.body.cancel().catch(() => {});
    return { ok: false, text: `fetch_url: response too large (${declaredLength} bytes > 1 MB cap)` };
  }

  const reader = res.body.getReader();
  const chunks = [];
  let total = 0;
  let tooLarge = false;
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      total += value.length;
      if (total > MAX_BODY_BYTES) {
        tooLarge = true;
        break;
      }
      chunks.push(value);
    }
  } catch (e) {
    clearTimeout(timer);
    if (tooLarge) {
      return { ok: false, text: "fetch_url: response body exceeded 1 MB cap, content truncated" };
    }
    const reason = e && e.name === "AbortError" ? `timed out after ${TIMEOUT_MS / 1000}s` : e && e.message ? e.message : "read error";
    return { ok: false, text: `fetch_url: ${reason}` };
  }
  clearTimeout(timer);
  if (tooLarge) {
    await reader.cancel().catch(() => {});
    return { ok: false, text: "fetch_url: response body exceeded 1 MB cap, content truncated" };
  }

  let bodyText;
  try {
    bodyText = Buffer.concat(chunks).toString("utf8");
  } catch {
    bodyText = "";
  }
  const isHtml = contentType.includes("html");
  const text = (isHtml ? htmlToText(bodyText) : bodyText).trim();
  if (!text) {
    return { ok: false, text: `fetch_url: no readable text content at ${url}` };
  }
  return { ok: true, text };
}

export const fetchUrlTool = defineTool({
  name: "fetch_url",
  label: "Fetch URL",
  description:
    "Fetch and read the text content of a URL (HTML or plain text). Runs server-side, body capped at ~1 MB and 30s timeout. Use only for urls present in the capture being analyzed.",
  parameters: Type.Object({
    url: Type.String({ description: "The http(s) URL to fetch and read." }),
