// Model stack for the capture agent service (Decision 02).
//
// Inference runs through OpenRouter via pi's ModelRuntime. The API key lives
// ONLY in this service's environment (OPENROUTER_API_KEY) — never in the
// browser. Default model deepseek/deepseek-v4-flash (thinking on), overridable
// with AGENT_MODEL.
//
// Auth + registry are in-memory: nothing sensitive is ever written to disk on
// the host, and the repo stays free of stray credential/registry files. The
// openrouter model is resolved from pi's built-in model registry.

import { AuthStorage, ModelRegistry } from "@earendil-works/pi-coding-agent";

export const DEFAULT_MODEL = "deepseek/deepseek-v4-flash";

// Design note on temperature: pi's session API does not expose a per-session
// temperature knob to SDK callers for reasoning models (temperature lives on
// provider StreamOptions that pi controls internally). The PRD's "~0.2" is
// honoured as documented intent; pi manages temperature for reasoning models
// itself. See outbox decisions.

export function createModelStack() {
  const authStorage = AuthStorage.inMemory();
  if (process.env.OPENROUTER_API_KEY) {
    authStorage.setRuntimeApiKey("openrouter", process.env.OPENROUTER_API_KEY);
  }
  const modelRegistry = ModelRegistry.inMemory(authStorage);
  return { authStorage, modelRegistry };
}

export function resolveModel(modelRegistry) {
  const id = process.env.AGENT_MODEL || DEFAULT_MODEL;
  const model = modelRegistry.find("openrouter", id);
  if (!model) {
    throw new Error(`Model not found on provider "openrouter": ${id}`);
  }
  return model;
}

