"""Capture Server — dumb receiver for the X capture instrument.

Accepts a single POST /api/capture, validates a recursive node tree (a tweet
together with curated comments, each of which is itself a node with the same
shape), stamps `captured_at` on the root on receipt, and appends one JSON
line to `artefacts.jsonl`. It does nothing else — no enrichment, no dedup, no
analysis.

Optionally the root may carry an `agent` envelope (produced by the capture
agent service) pointing at the saved conversation evidence; if present it must
carry `sessionId` + `sessionFile`. The server does not verify the session file
exists at save time — session persistence is the agent service's contract.

It also exposes GET /search — a thin read API over the derived SQLite FTS5
index (see index.py / bin/rebuild-index.py).

Fixed defaults:
  - data file: data/artefacts.jsonl beside this file
  - port: 8765
Each may be overridden by a single env var (CAPTURE_DATA, CAPTURE_PORT,
CAPTURE_INDEX). No config file, no CLI flags.
"""

import json
import os
from datetime import datetime, timezone
from pathlib import Path

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse

from index import CaptureIndex

DEFAULT_PORT = 8765
DEFAULT_DATA_PATH = Path(__file__).resolve().parent / "data" / "artefacts.jsonl"
DEFAULT_INDEX_PATH = Path(__file__).resolve().parent / "data" / "index.db"

# tweet_url is the anchor and the only required field on every node; the rest
# (including children) is optional and may be empty.
REQUIRED_FIELDS = ("tweet_url",)

app = FastAPI(title="Capture Server")


def data_path() -> Path:
    return Path(os.environ.get("CAPTURE_DATA", DEFAULT_DATA_PATH))


def index_path() -> Path:
    return Path(os.environ.get("CAPTURE_INDEX", DEFAULT_INDEX_PATH))


def _index() -> CaptureIndex:
    return CaptureIndex(index_path())


def append_artefact(artefact: dict, path: Path | None = None) -> None:
    """Append one artefact as a JSON line, write + flush. Returns None."""
    target = path if path is not None else data_path()
    with target.open("a", encoding="utf-8") as f:
        f.write(json.dumps(artefact, ensure_ascii=False) + "\n")
        f.flush()


def validate_node(node, path="root") -> None:
    """Validate a node recursively. Raises ValueError with a descriptive
    message on the first problem found. Every nested child must have a
    tweet_url."""
    if not isinstance(node, dict):
        raise ValueError(f"{path} must be an object")
    if not node.get("tweet_url"):
        raise ValueError(f"{path} is missing required field 'tweet_url'")
    children = node.get("children") or []
    if not isinstance(children, list):
        raise ValueError(f"{path}.children must be a list")
    for i, child in enumerate(children):
        validate_node(child, f"{path}.children[{i}]")


@app.post("/api/capture")
async def capture(request: Request):
    try:
        body = await request.json()
    except Exception:
        return JSONResponse(
            status_code=400, content={"status": "error", "error": "invalid JSON body"}
        )

    if not isinstance(body, dict):
        return JSONResponse(
            status_code=400, content={"status": "error", "error": "payload must be an object"}
        )

    try:
        validate_node(body)
    except ValueError as exc:
        return JSONResponse(
            status_code=400,
            content={"status": "error", "error": str(exc)},
        )

    agent = body.get("agent")
    if agent is not None:
        if not isinstance(agent, dict):
            return JSONResponse(
                status_code=400,
                content={"status": "error", "error": "agent must be an object when present"},
            )
        if not agent.get("sessionId") or not agent.get("sessionFile"):
            return JSONResponse(
                status_code=400,
                content={"status": "error", "error": "agent envelope must carry sessionId and sessionFile"},
            )

    captured_at = datetime.now(timezone.utc).isoformat()
    artefact = {
        "tweet_url": body["tweet_url"],
        "author": body.get("author", ""),
        "tweet_text": body.get("tweet_text", ""),
        "links": body.get("links", []),
        "parent_url": body.get("parent_url"),
        "notes": body.get("notes", ""),
        "children": body.get("children", []),
        "captured_at": captured_at,
    }
    if agent is not None:
        artefact["agent"] = agent

    append_artefact(artefact)
    return {"status": "saved", "captured_at": captured_at}


@app.get("/search")
async def search(q: str = "", author: str | None = None, since: str | None = None, limit: int = 50):
    """Read API over the derived FTS5 index (BM25 relevance-ranked).

    GET /search?q=arxiv&author=@user&since=2026-08-01T00:00:00+00:00&limit=50

    The index is derived from artefacts.jsonl; if it does not exist yet it is
    rebuilt on the fly so a fresh checkout still answers.
    """
    idx = _index()
    if not idx.exists():
        # derived + rebuildable: safest to build on first read so /search works
        # right after a fresh start without a manual rebuild step.
        try:
            idx.rebuild(data_path())
        except Exception:
            return JSONResponse(status_code=500, content={"status": "error", "error": "could not build index"})

    try:
        items, total = idx.search(q=q or None, author=author or None, since=since or None, limit=limit)
    except ValueError as exc:
        return JSONResponse(status_code=400, content={"status": "error", "error": str(exc)})
    except Exception as exc:  # pragma: no cover - defensive
        return JSONResponse(status_code=500, content={"status": "error", "error": str(exc)})
    return {"items": items, "total": total, "rank": True}



def main() -> None:
    import uvicorn

    port = int(os.environ.get("CAPTURE_PORT", DEFAULT_PORT))
    uvicorn.run(app, host="127.0.0.1", port=port)


if __name__ == "__main__":
    main()
